{"sql": "-- Create LEGO database schema
-- Reference Tables
CREATE TABLE IF NOT EXISTS lego_themes (
    theme_id INTEGER PRIMARY KEY,
    theme_name VARCHAR(255) NOT NULL,
    parent_id INTEGER
);

CREATE TABLE IF NOT EXISTS lego_colors (
    color_id INTEGER PRIMARY KEY,
    color_name VARCHAR(100) NOT NULL,
    rgb VARCHAR(6),
    is_trans BOOLEAN DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS lego_part_categories (
    part_category_id INTEGER PRIMARY KEY,
    category_name VARCHAR(255) NOT NULL
);

CREATE TABLE IF NOT EXISTS lego_parts (
    part_num VARCHAR(20) PRIMARY KEY,
    part_name VARCHAR(255) NOT NULL,
    part_category_id INTEGER REFERENCES lego_part_categories(part_category_id)
);

-- Main Data Tables
CREATE TABLE IF NOT EXISTS lego_sets (
    set_num VARCHAR(20) PRIMARY KEY,
    set_name VARCHAR(255) NOT NULL,
    year INTEGER,
    theme_id INTEGER REFERENCES lego_themes(theme_id),
    num_parts INTEGER
);

CREATE TABLE IF NOT EXISTS lego_inventories (
    inventory_id INTEGER PRIMARY KEY,
    version INTEGER,
    set_num VARCHAR(20) REFERENCES lego_sets(set_num)
);

CREATE TABLE IF NOT EXISTS lego_inventory_parts (
    inventory_id INTEGER REFERENCES lego_inventories(inventory_id),
    part_num VARCHAR(20) REFERENCES lego_parts(part_num),
    color_id INTEGER REFERENCES lego_colors(color_id),
    quantity INTEGER,
    is_spare BOOLEAN DEFAULT FALSE,
    PRIMARY KEY (inventory_id, part_num, color_id, is_spare)
);"}

{"sql": "-- Step 1: Create the theme assignment function
CREATE OR REPLACE FUNCTION get_user_theme_id()
RETURNS INTEGER AS $$
BEGIN
    -- Check if the current user is the theme_analyst role
    IF current_user = 'theme_analyst' THEN
        RETURN 18;  -- Star Wars theme
    END IF;

    -- Default: return NULL (no access) for other users
    -- This can be extended in the future to support other roles/themes
    RETURN NULL;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- Grant execute permission on the function to public
GRANT EXECUTE ON FUNCTION get_user_theme_id() TO PUBLIC;"}

{"sql": "-- Step 2: Create the theme_analyst role
-- First, drop the role if it exists (with cascade to remove dependencies)
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'theme_analyst') THEN
        -- Revoke all privileges first
        REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA public FROM theme_analyst;
        REVOKE ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public FROM theme_analyst;
        REVOKE ALL PRIVILEGES ON ALL FUNCTIONS IN SCHEMA public FROM theme_analyst;
        REVOKE ALL PRIVILEGES ON SCHEMA public FROM theme_analyst;
        -- Drop owned objects
        DROP OWNED BY theme_analyst;
        -- Drop the role
        DROP ROLE theme_analyst;
    END IF;
END
$$;

-- Create the new role
CREATE ROLE theme_analyst WITH LOGIN PASSWORD 'secure_password';

-- Grant USAGE on schema
GRANT USAGE ON SCHEMA public TO theme_analyst;

-- Grant SELECT permissions on reference tables
GRANT SELECT ON lego_themes TO theme_analyst;
GRANT SELECT ON lego_colors TO theme_analyst;
GRANT SELECT ON lego_parts TO theme_analyst;
GRANT SELECT ON lego_part_categories TO theme_analyst;

-- Grant SELECT permissions on main data tables
GRANT SELECT ON lego_sets TO theme_analyst;
GRANT SELECT ON lego_inventories TO theme_analyst;
GRANT SELECT ON lego_inventory_parts TO theme_analyst;

-- Explicitly deny INSERT, UPDATE, DELETE (PostgreSQL doesn't have DENY, so we just don't grant)
-- The role will only have SELECT permissions as granted above"}

{"sql": "-- Step 3: Enable Row-Level Security on main data tables
ALTER TABLE lego_sets ENABLE ROW LEVEL SECURITY;
ALTER TABLE lego_inventories ENABLE ROW LEVEL SECURITY;
ALTER TABLE lego_inventory_parts ENABLE ROW LEVEL SECURITY;

-- Check RLS status
SELECT 
    schemaname,
    tablename,
    rowsecurity
FROM pg_tables
WHERE schemaname = 'public' 
    AND tablename IN ('lego_sets', 'lego_inventories', 'lego_inventory_parts');"}

{"sql": "-- Create a function to test RLS as theme_analyst
CREATE OR REPLACE FUNCTION test_theme_analyst_access()
RETURNS TABLE (
    test_name TEXT,
    result TEXT
) AS $$
DECLARE
    star_wars_sets_count INTEGER;
    technic_sets_count INTEGER;
    total_sets_count INTEGER;
    star_wars_inventories_count INTEGER;
    star_wars_parts_count INTEGER;
    set_details TEXT;
BEGIN
    -- Temporarily set the session to theme_analyst role
    SET LOCAL ROLE theme_analyst;

    -- Test 1: Count Star Wars sets (should be 2)
    SELECT COUNT(*) INTO star_wars_sets_count
    FROM lego_sets
    WHERE theme_id = 18;

    RETURN QUERY SELECT 'Star Wars sets count'::TEXT, star_wars_sets_count::TEXT;

    -- Test 2: Count Technic sets (should be 0 due to RLS)
    SELECT COUNT(*) INTO technic_sets_count
    FROM lego_sets
    WHERE theme_id = 1;

    RETURN QUERY SELECT 'Technic sets count (should be 0)'::TEXT, technic_sets_count::TEXT;

    -- Test 3: Count total visible sets (should be 2 - only Star Wars)
    SELECT COUNT(*) INTO total_sets_count
    FROM lego_sets;

    RETURN QUERY SELECT 'Total visible sets'::TEXT, total_sets_count::TEXT;

    -- Test 4: Get Star Wars set details
    SELECT STRING_AGG(set_num || ' - ' || set_name, '; ' ORDER BY set_num) INTO set_details
    FROM lego_sets;

    RETURN QUERY SELECT 'Visible set details'::TEXT, COALESCE(set_details, 'No sets visible');

    -- Test 5: Count Star Wars inventories
    SELECT COUNT(*) INTO star_wars_inventories_count
    FROM lego_inventories;

    RETURN QUERY SELECT 'Star Wars inventories count'::TEXT, star_wars_inventories_count::TEXT;

    -- Test 6: Count Star Wars inventory parts
    SELECT COUNT(DISTINCT (inventory_id, part_num, color_id)) INTO star_wars_parts_count
    FROM lego_inventory_parts;

    RETURN QUERY SELECT 'Star Wars inventory parts count'::TEXT, star_wars_parts_count::TEXT;

    -- Reset role
    RESET ROLE;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Run the test
SELECT * FROM test_theme_analyst_access();"}
